 92	    // ------------------------------------------------------------------
 93	    // Badge cell — wrapper <div> keeps data-repo-id so polling updates can
 94	    // locate and replace badge contents without touching the rest of the row.
 95	    // ------------------------------------------------------------------
 96	    const badgeCell = document.createElement('td');
 97	    badgeCell.className = 'repo-badge-cell';
 98	
 99	    const badgeWrapper = document.createElement('div');
100	    badgeWrapper.dataset.repoId = repoId;
101	    badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
102	    badgeCell.appendChild(badgeWrapper);
103	
104	    // ------------------------------------------------------------------
105	    // Actions cell — "Git GUI" button (always present) + optional "Browse"
106	    // ------------------------------------------------------------------
107	    const actionsCell = document.createElement('td');
108	    actionsCell.className = 'repo-actions-cell';
109	
110	    const openBtn = document.createElement('button');
111	    openBtn.type        = 'button';
112	    openBtn.className   = 'btn btn-secondary btn-sm';
113	    openBtn.textContent = 'Git GUI';
114	    openBtn.title       = 'Open this repository in GitHub Desktop.';
115	
116	    openBtn.addEventListener('click', async () => {
117	        openBtn.disabled    = true;
118	        openBtn.textContent = 'Opening…';
119	        try {
120	            await api.workspaces.launch.githubDesktop(projectId, wid, repoId);
121	        } catch (err) {
122	            // Import showToast lazily to avoid a hard dependency cycle; callers
123	            // that need richer error UX can wrap this function.
124	            const { showToast } = await import('./toast.js');
125	            showToast(err.message || 'Failed to open GitHub Desktop.', 'error');
126	        } finally {
127	            openBtn.disabled    = false;
128	            openBtn.textContent = 'Git GUI';
129	        }
130	    });
131	
132	    actionsCell.appendChild(openBtn);
133	
134	    // Browse button — shown only when webserverUrl is configured.
135	    if (webserverUrl) {
136	        const browseBtn = document.createElement('button');
137	        browseBtn.type        = 'button';
138	        browseBtn.className   = 'btn btn-secondary btn-sm';
139	        browseBtn.textContent = 'Browse';
140	        browseBtn.title       = 'Open this repository in the browser via the configured webserver URL.';
141	
142	        browseBtn.addEventListener('click', () => {
143	            const url = `${webserverUrl}/${encodeURIComponent(projectId)}/${encodeURIComponent(wid)}/${encodeURIComponent(repoId)}/`;
144	            window.open(url, '_blank');
145	        });
146	
147	        // Insert Browse before Git GUI so the visual order is: Browse → Git GUI.
148	        actionsCell.insertBefore(browseBtn, openBtn);
149	    }
150	
151	    return { branchCell, badgeCell, actionsCell };
